Body:
I was able to temporarily hack this to work until fix is in place.

Note: this is not a long term solution, just an unblocker until this issue is fixed.

```typescript
// File: ~/.opencode/plugins/adaptiveThinking.ts
export const adaptiveThinking: import("@opencode-ai/plugin").Plugin =
  async () => ({
      loader: async () => {
        return {
          fetch: async (url: RequestInfo | URL, init?: RequestInit) => {
            const body = init?.body
              ? JSON.parse(init.body as string)
              : undefined;

            if (body?.thinking?.budget_tokens === -1) {
              body.thinking = { type: "adaptive" };
              return fetch(url, { ...init, body: JSON.stringify(body) });
            }
            return fetch(url, init);
          },
        };
      },
    },

    // Shim: rewrite adaptive -> enabled with sentinel budget so SDK Zod passes,
    // then the custom fetch above detects budget_tokens:-1 and patches to adaptive.
    "chat.params": async (_input, output) => {
      if (output.options?.thinking?.type === "adaptive") {
        output.options.thinking = { type: "enabled", budgetTokens: -1 };
      }
    },
  });
```


